def get_axioms() -> list:
    # Linking precondition (added directly, not negated): the promoted result
    # type of self*other must be safely castable to the out tensor's dtype
    # (TensorIterator: "result type X can't be cast to the desired output type Y"),
    # and mul has no kernel for Float8_e8m0fnu inputs.
    _a = TensorVar('self')
    _b = TensorVar('other')
    _out = TensorVar('out')
    return [
        canCast(result_type(_a.dtype, _b.dtype), _out.dtype),
        _a.dtype != IntVal(FLOAT8_E8M0FNU),
        _b.dtype != IntVal(FLOAT8_E8M0FNU),
    ]


def get_vars() -> dict:
    self = TensorVar('self')
    other = TensorVar('other')
    out = TensorVar('out')
    return {'self': self, 'other': other, 'out': out}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s
